export class PlanError extends Error {
  constructor(code, message, extra = {}) {
    super(message);
    this.name = "PlanError";
    this.code = code;
    Object.assign(this, extra);
  }
}

function isPlainObject(value) {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    return false;
  }
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function isNonEmptyString(value) {
  return typeof value === "string" && value.length > 0;
}

export function buildPlan(tasks) {
  if (!Array.isArray(tasks)) {
    throw new PlanError("INVALID_TASKS", "tasks must be an array");
  }

  const depsById = new Map();

  for (let index = 0; index < tasks.length; index++) {
    const task = tasks[index];
    if (!isPlainObject(task) || !isNonEmptyString(task.id)) {
      throw new PlanError("INVALID_TASK", "task must be a plain object with a non-empty string id", {
        index,
      });
    }

    const { id } = task;
    if (depsById.has(id)) {
      throw new PlanError("DUPLICATE_ID", `duplicate task id: ${id}`, { id });
    }

    const deps = task.deps;
    if (deps !== undefined) {
      if (!Array.isArray(deps) || !deps.every(isNonEmptyString)) {
        throw new PlanError(
          "INVALID_DEPS",
          `deps of task ${id} must be an array of non-empty strings`,
          { id },
        );
      }
    }

    depsById.set(id, new Set(deps ?? []));
  }

  for (const [id, deps] of depsById) {
    for (const dependency of deps) {
      if (!depsById.has(dependency)) {
        throw new PlanError("UNKNOWN_DEP", `task ${id} depends on unknown task ${dependency}`, {
          id,
          dependency,
        });
      }
    }
  }

  const pending = new Map(depsById);
  const placed = new Set();
  const waves = [];

  while (pending.size > 0) {
    const wave = [];
    for (const [id, deps] of pending) {
      let ready = true;
      for (const dependency of deps) {
        if (!placed.has(dependency)) {
          ready = false;
          break;
        }
      }
      if (ready) {
        wave.push(id);
      }
    }

    if (wave.length === 0) {
      throw new PlanError("CYCLE", "dependency graph contains a cycle", {
        cycle: [...pending.keys()].sort(),
      });
    }

    wave.sort();
    for (const id of wave) {
      placed.add(id);
      pending.delete(id);
    }
    waves.push(wave);
  }

  return { waves, order: waves.flat() };
}

